      source: 'SCERT Bihar p.3-4 / NCERT Class 10 p.13',
      answer: 'भूमिका:\n1830 की जुलाई क्रांति ने मेटरनिख द्वारा 1815 में स्थापित रूढ़िवादी व्यवस्था पर पहला भीषण प्रहार किया। इस क्रांति ने यह साबित कर दिया कि नेपोलियन के बाद स्थापित की गई पुरातन व्यवस्था अब यूरोप की जनता को स्वीकार नहीं थी।\n\n1. क्रांति के प्रमुख कारण:\n• चार्ल्स दशम की निरंकुशता: 1824 में फ्रांस का राजा बना चार्ल्स दशम घोर प्रतिक्रियावादी था। वह दैवीय अधिकारों के राजतंत्र को फिर से थोपना चाहता था।\n• पोलिग्नेक की नियुक्ति: उसने उदारवादियों के विरोध को दबाने के लिए कट्टर रूढ़िवादी पोलिग्नेक को प्रधानमंत्री बनाया।\n• चार दमनकारी अध्यादेश (25 जुलाई 1830): पोलिग्नेक ने प्रेस की स्वतंत्रता छीन ली, नवनिर्वाचित प्रतिनिधि सभा को भंग कर दिया, मताधिकार को संकुचित कर दिया और नए चुनाव की घोषणा की।\n\n2. क्रांति की प्रमुख घटनाएं:\n• पेरिस में 27 से 29 जुलाई 1830 तक "तीन गौरवशाली दिन" (Three Glorious Days) चले, जिसमें छात्रों, मजदूरों और नागरिकों ने सड़कों पर मोर्चाबंदी कर दी।\n• सेना ने जनता पर गोली चलाने से इनकार कर दिया। विवश होकर चार्ल्स दशम ने गद्दी छोड़ दी और इंग्लैंड भाग गया।\n• उदारवादी नेताओं ने ऑर्लियंस वंश के लुई फिलिप को एक संवैधानिक राजा के रूप में सिंहासन पर बैठाया।\n\n3. यूरोपीय राष्ट्रवाद पर प्रभाव:\n• बेल्जियम की स्वतंत्रता: वियना कांग्रेस ने बेल्जियम को नीदरलैंड्स के अधीन कर दिया था। जुलाई क्रांति से प्रेरित होकर बेल्जियम के लोगों ने विद्रोह किया और बेल्जियम एक स्वतंत्र राष्ट्र बन गया।\n• पोलैंड में विद्रोह: रूस के दमनकारी शासन के खिलाफ पोलिश राष्ट्रवादियों ने हथियार उठाए।\n• इटली और जर्मनी में हलचल: मेजिनी ने इटली में और उदारवादियों ने जर्मन राज्यों में संवैधानिक सुधारों की मांग तेज कर दी।',
      explanation: 'मेटरनिख ने हताश होकर कहा था: "जब फ्रांस छींकता है, तो बाकी यूरोप को सर्दी-जुकाम हो जाता है।"'
