      type: 'Long',
      difficulty: 'Hard',
      isPyq: true,
      pyqYear: 'BSEB 2017, 2021',
      topic: 'स्कॉटलैंड व आयरलैंड का दमनकारी विलय',
      source: 'NCERT Class 10 p.22-23 / SCERT Bihar',
      answer: 'भूमिका:\nब्रिटिश राष्ट्र का निर्माण किसी लोकतांत्रिक सहमति से नहीं हुआ, बल्कि आंग्ल (अंग्रेज) जाति ने अपनी सैन्य, आर्थिक और राजनीतिक शक्ति के बल पर पड़ोसी स्कॉटलैंड और आयरलैंड की अनूठी पहचान को कुचलकर अपना प्रभुत्व स्थापित किया।\n\n1. स्कॉटलैंड का दमन और विलय:\n• 1707 के \'एक्ट ऑफ यूनियन\' द्वारा इंग्लैंड और स्कॉटलैंड को मिलाकर \'यूनाइटेड किंगडम ऑफ ग्रेट ब्रिटेन\' बनाया गया।\n• इसके बाद ब्रिटिश संसद में अंग्रेजी सांसदों का भारी बहुमत हो गया। स्कॉटलैंड की विशिष्ट पहचान को दबाने के लिए योजनाबद्ध कदम उठाए गए:\n  - स्कॉटिश हाइलैंडर्स को अपनी पारंपरिक राष्ट्रीय पोशाक (Kilt) पहनने से रोक दिया गया।\n  - उनकी मूल भाषा \'गेलिक\' (Gaelic) बोलने पर कड़े प्रतिबंध लगाए गए।\n  - हजारों हाइलैंडर्स को उनकी पुश्तैनी जमीनों से जबरन बेदखल कर देश छोड़ने पर मजबूर किया गया।\n\n2. आयरलैंड का रक्तरंजित विलय:\n• आयरलैंड में कैथोलिकों और प्रोटेस्टेंटों के बीच गहरा धार्मिक विभाजन था।\n• अंग्रेजों ने अल्पसंख्यक प्रोटेस्टेंटों का साथ दिया और बहुसंख्यक कैथोलिकों के अधिकारों को कुचल दिया।\n• 1798 में वोल्फ टोन के नेतृत्व में आयरिश राष्ट्रवादियों ने विद्रोह किया, जिसे अंग्रेजों ने क्रूरता से दबा दिया।\n• 1801 में एक नए कानून द्वारा आयरलैंड को जबरन यूनाइटेड किंगडम में शामिल कर लिया गया।\n\n3. परिणाम:\n• इस प्रकार एक ऐसा \'ग्रेट ब्रिटेन\' बना जिसकी पहचान आंग्ल भाषा, यूनियन जैक झंडे और आंग्ल संस्कृति पर टिकी थी, जबकि स्कॉटलैंड और आयरलैंड केवल अधीनस्थ सहयोगी बनकर रह गए।',
      explanation: 'ब्रिटेन का एकीकरण राष्ट्रवाद के नाम पर छोटे सांस्कृतिक समूहों के दमन और आंग्ल वर्चस्व की स्थापना का उदाहरण है।'
