      source: 'NCERT Class 10 p.16-22 / SCERT Bihar',
      answer: 'भूमिका:\n19वीं सदी के उत्तरार्ध (1859-1871) में यूरोप के दो प्रमुख देशों—इटली और जर्मनी का एकीकरण संपन्न हुआ। दोनों ही प्रक्रियाएं यूरोप की पुरातन व्यवस्था को चुनौती देने वाली थीं। इन दोनों एकीकरणों में कई महत्वपूर्ण समानताएं और कुछ बुनियादी भिन्नताएं थीं।\n\n1. दोनों के एकीकरण में प्रमुख समानताएं:\n• दोनों ही देश विखंडित थे: 1815 में जर्मनी 39 राज्यों में और इटली 7 राज्यों में बंटा था।\n• ऑस्ट्रिया सबसे बड़ा साझा शत्रु था: इटली के लोम्बार्डी-वेनेशिया पर ऑस्ट्रिया का कब्जा था, जबकि जर्मन परिसंघ पर ऑस्ट्रिया का राजनीतिक प्रभुत्व था। दोनों को ऑस्ट्रिया को युद्ध में हराना पड़ा।\n• एक शक्तिशाली राज्य द्वारा नेतृत्व: जर्मनी का एकीकरण \'प्रशा\' राज्य के नेतृत्व में हुआ, जबकि इटली का एकीकरण \'सार्डिनिया-पीडमोंट\' के नेतृत्व में हुआ।\n• कूटनीतिज्ञ प्रधानमंत्रियों की भूमिका: जर्मनी में बिस्मार्क और इटली में काउंट कावूर ने अपनी चतुर कूटनीति से विदेशी शक्तियों का लाभ उठाकर एकीकरण का मार्ग प्रशस्त किया।\n• 1870-71 में पूर्णता: फ्रांस-प्रशा युद्ध (1870) के परिणामस्वरूप जर्मनी का एकीकरण पूरा हुआ और उसी युद्ध के कारण रोम से फ्रांसीसी सेना हटने पर इटली का एकीकरण भी 1870 में पूर्ण हुआ।\n\n2. दोनों के एकीकरण में मुख्य भिन्नताएं:\n• जनांदोलन बनाम सैन्यवाद: इटली के एकीकरण में मेजिनी के वैचारिक आंदोलन और गैरीबाल्डी के लोकप्रिय छापामार जनसंघर्ष (लाल कुर्ती) की बहुत बड़ी भूमिका थी। इसके विपरीत, जर्मनी का एकीकरण ऊपर से शासक वर्ग और बिस्मार्क की सेना द्वारा "रक्त और लौह" से किया गया, जिसमें जनांदोलन की भूमिका नगण्य थी।\n• विदेशी सहायता: इटली को फ्रांस (1859) और प्रशा (1866) की प्रत्यक्ष सैन्य सहायता की जरूरत पड़ी। जबकि प्रशा ने स्वयं अपने दम पर तीनों युद्ध जीते।\n• धर्म और पोप की बाधा: इटली के मध्य में पोप का स्वतंत्र राज्य था और कैथोलिक धर्म एक बड़ी बाधा था, जबकि जर्मनी में पोप का ऐसा कोई प्रत्यक्ष भौगोलिक राज्य नहीं था।\n• एकीकरण के बाद का स्वरूप: इटली में एक उदारवादी संवैधानिक राजतंत्र बना, जबकि जर्मनी में एक शक्तिशाली, सैन्यवाद-प्रधान और अर्ध-निरंकुश साम्राज्य स्थापित हुआ।',
      explanation: 'जर्मनी का एकीकरण सैन्य शक्ति और कूटनीति की विजय थी, जबकि इटली का एकीकरण कूटनीति, जनक्रांति और त्याग का अद्भुत संगम था।'
